def solve(board: list[list[str]]) -> list[list[str]]:
    if not board:
        return board
    R, C = len(board), len(board[0])

    def dfs(r, c):
        if r < 0 or r >= R or c < 0 or c >= C or board[r][c] != 'O':
            return
        board[r][c] = 'T'
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    # Mark border-connected 'O's as 'T'
    for r in range(R):
        dfs(r, 0)
        dfs(r, C - 1)
    for c in range(C):
        dfs(0, c)
        dfs(R - 1, c)

    for r in range(R):
        for c in range(C):
            if board[r][c] == 'O':
                board[r][c] = 'X'
            elif board[r][c] == 'T':
                board[r][c] = 'O'
    return board

reference_solution.javascript:
function solve(board) {
  if (!board || board.length === 0) return board;
  const R = board.length, C = board[0].length;
  function dfs(r, c) {
    if (r < 0 || r >= R || c < 0 || c >= C || board[r][c] !== 'O') return;
    board[r][c] = 'T';
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
  }
  for (let r = 0; r < R; r++) { dfs(r, 0); dfs(r, C - 1); }
  for (let c = 0; c < C; c++) { dfs(0, c); dfs(R - 1, c); }
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (board[r][c] === 'O') board[r][c] = 'X';
      else if (board[r][c] === 'T') board[r][c] = 'O';
    }
  }
  return board;
}
